import java.io.*;

public class FileReadVulnerable {
    public void readFile(String userInput) {
        // vulnerable: Using user input directly in file path construction leads to Path Traversal
        // An attacker can input "../../etc/passwd" to read sensitive system files
        String filePath = "/var/data/" + userInput;

        File file = new File(filePath);
        try (FileReader fr = new FileReader(file);
             BufferedReader br = new BufferedReader(fr)) {
            String line = br.readLine();
            System.out.println(line);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
