import java.io.*;
import java.nio.file.*;

public class FileReadSecure {
    public void readFile(String userInput) {
        // Base directory where files are allowed to be accessed
        Path baseDir = Paths.get("/var/data");

        // Resolve the user input against the base directory
        Path filePath = baseDir.resolve(userInput).normalize();

        // Security check: Ensure the resolved path is still within the base directory
        // This prevents directory traversal attacks like "../../etc/passwd"
        if (!filePath.startsWith(baseDir)) {
            throw new SecurityException("Access denied: Path traversal attempt detected");
        }

        try (FileReader fr = new FileReader(filePath.toFile());
             BufferedReader br = new BufferedReader(fr)) {
            String line = br.readLine();
            System.out.println(line);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
